insert into public.spell_definitions(slug,name,description,enabled,spell_kind,damage_type,mana_cost,required_level,power_multiplier,flat_power,status_effect_type,status_effect_chance,status_effect_turns,status_effect_potency,support_effect_type,support_value,support_turns) values
('weakening_spark','Ослабляющая искра','Быстрый разряд: небольшой электрический урон и 55% шанс Ослабления на 2 хода (-10% исходящего урона).',true,'damage','lightning',12,1,0.75,2,'weaken',55,2,10,null,0,0),
('sand_veil','Песчаная завеса','Защитная завеса вокруг выбранной цели. Следующий входящий удар уменьшается на 55%. Можно накладывать на союзника.',true,'guard',null,15,1,0,0,null,0,0,0,'guard',55,1),
('healing_spark','Целебный импульс','Недорогое раннее лечение. Слабее «Заживления», зато доступно раньше и расходует меньше маны.',true,'heal',null,14,2,0.75,10,null,0,0,0,null,0,0),
('venom_spore','Ядовитая спора','Земляной сгусток спор: небольшой урон и 70% шанс Яда на 3 хода.',true,'damage','earth',15,2,0.8,3,'poison',70,3,5,null,0,0),
('exposing_rune','Руна раскрытия','Арканная руна повреждает защитный рисунок цели и с 70% шансом накладывает Уязвимость на 2 хода.',true,'damage','arcane',18,3,0.7,3,'vulnerable',70,2,12,null,0,0),
('combat_impulse','Боевой импульс','Усиливает следующие 2 прямые атаки на 15%. Работает и с физическими, и с магическими атаками.',true,'buff',null,20,3,0,0,null,0,0,0,'empower',15,2),
('moon_frost','Лунный озноб','Лунный урон и 80% шанс Охлаждения на 2 хода (-18% исходящего урона цели).',true,'damage','moon',22,4,1,6,'chill',80,2,18,null,0,0)
