insert into public.equipment_sets(slug,name,description,total_pieces,enabled) values
('warden_scout','Следопыт Вардена','Лёгкий ранний комплект разведчика: ловкость, удача и уверенная физическая атака.',3,true),
('liaven_apprentice','Ученик Лиавена','Комплект для первых полноценных магических билдов: интеллект, магический урон и возврат маны.',3,true),
('stonewatch','Каменный караул','Тяжёлый комплект стража для раннего танкования и уверенного блока.',4,true),
('ash_circle','Пепельный круг','Редкий комплект боевого мага пустыни. Усиливает заклинания и поддерживает запас маны.',3,true)
